python3 -c "
import json
files = ('harness/policy/bundle.json', 'examples/steer/policy/bundle.v1.json', 'examples/steer/policy/bundle.v2.json')
paths, rules = set(), 0
for f in files:
    b = json.load(open(f))
    rules += len(b['rules'])
    for r in b['rules']:
        for c in r['when']:
            paths.add(c['path'])
            if c['op'].endswith('_field'): paths.add(c['value'])
print('rules_scanned=%d paths_naming_the_door=%s' % (rules, sorted(p for p in paths if 'entry' in p or 'kind' in p or 'door' in p)))
"
